css:
/* From Uiverse.io by alexruix - Tags: form, sign-up */
.__UIV_SCOPE__ .form-box {
  max-width: 300px;
  background: #f1f7fe;
  overflow: hidden;
  border-radius: 16px;
  color: #010101;
}

.__UIV_SCOPE__ .form {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 32px 24px 24px;
  gap: 16px;
  text-align: center;
}

/*Form text*/
.__UIV_SCOPE__ .title {
  font-weight: bold;
  font-size: 1.6rem;
}

.__UIV_SCOPE__ .subtitle {
  font-size: 1rem;
  color: #666;
}

/*Inputs box*/
.__UIV_SCOPE__ .form-container {
  overflow: hidden;
  border-radius: 8px;
  background-color: #fff;
  margin: 1rem 0 .5rem;
  width: 100%;
}

.__UIV_SCOPE__ .input {
  background: none;
  border: 0;
  outline: 0;
  height: 40px;
  width: 100%;
  border-bottom: 1px solid #eee;
  font-size: .9rem;
  padding: 8px 15px;
}

.__UIV_SCOPE__ .form-section {
  padding: 16px;
  font-size: .85rem;
  background-color: #e0ecfb;
  box-shadow: rgb(0 0 0 / 8%) 0 -1px;
}

.__UIV_SCOPE__ .form-section a {
  font-weight: bold;
  color: #0066ff;
  transition: color .3s ease;
}

.__UIV_SCOPE__ .form-section a:hover {
  color: #005ce6;
  text-decoration: underline;
}

/*Button*/
.__UIV_SCOPE__ .form button {
  background-color: #0066ff;
  color: #fff;
  border: 0;
  border-radius: 24px;
  padding: 10px 16px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color .3s ease;
}

.__UIV_SCOPE__ .form button:hover {
  background-color: #005ce6;
}
